import ReactDOM from 'react-dom';

import {
  HYDRATED_PNG_COPY_ATTR,
  PNG_COPY_ACTION_SELECTOR,
  PNG_COPY_FEEDBACK_ID_PREFIX,
  TEMPLATE_SLIDE_SELECTOR,
  TEMPLATE_SLIDE_TEST_ID_PREFIX,
} from 'utils/pageCache/pngCopyCacheConstants';

import { TemplateSlidePngCopyAction } from '../components/PngCopyAction/TemplateSlidePngCopyAction';

export const hydratePngCopyActions = (container: HTMLElement): (() => void) => {
  const cleanups: Array<() => void> = [];

  container.querySelectorAll(TEMPLATE_SLIDE_SELECTOR).forEach((slideNode) => {
    if (!(slideNode instanceof HTMLElement)) return;

    slideNode.querySelectorAll(PNG_COPY_ACTION_SELECTOR).forEach((node) => {
      if (!node.closest(`[${HYDRATED_PNG_COPY_ATTR}]`)) {
        node.remove();
      }
    });

    if (slideNode.querySelector(`[${HYDRATED_PNG_COPY_ATTR}]`)) return;

    const content = slideNode.firstElementChild;
    if (!(content instanceof HTMLElement)) return;

    const mountNode = document.createElement('div');
    mountNode.dataset.hydratedPngCopy = 'true';
    content.insertBefore(mountNode, content.firstChild);

    const slideTestId = slideNode.dataset.testid;
    const slideSuffix = slideTestId?.startsWith(TEMPLATE_SLIDE_TEST_ID_PREFIX)
      ? slideTestId.slice(TEMPLATE_SLIDE_TEST_ID_PREFIX.length)
      : String(cleanups.length);
    const feedbackId = `${PNG_COPY_FEEDBACK_ID_PREFIX}-${slideSuffix}`;
    const slideRef = { current: slideNode };

    ReactDOM.render(
      <TemplateSlidePngCopyAction
        slideRef={slideRef}
        feedbackId={feedbackId}
      />,
      mountNode,
    );

    cleanups.push(() => {
      ReactDOM.unmountComponentAtNode(mountNode);
      mountNode.remove();
    });
  });

  return () => {
    cleanups.forEach((cleanup) => cleanup());
  };
};
